class Solution {
  public long minCost(int[] nums, int x) {
    int n = nums.length;
    long[] best = new long[n];
    for (int i = 0; i < n; i++) best[i] = nums[i];
    long ans = Long.MAX_VALUE;
    for (int rotations = 0; rotations < n; rotations++) {
      long cost = (long) rotations * x;
      for (int i = 0; i < n; i++) {
        best[i] = Math.min(best[i], nums[(i + rotations) % n]);
        cost += best[i];
      }
      ans = Math.min(ans, cost);
    }
    return ans;
  }
}
